def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objects = []
    seen = set()
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < len(grid) and 0 <= xx < len(row) and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objects.append(cells)
    boxes = []
    for cells in objects:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
        patch=[row[c0:c1+1] for row in grid[r0:r1+1]]
        boxes.append(patch)
    canvas = next((p for p in boxes if any(5 in row for row in p)), boxes[0])
    out = [row[:] for row in canvas]
    for patch in boxes:
        if patch is canvas:
            continue
        for r,row in enumerate(patch):
            for c,v in enumerate(row):
                if v != patch[0][0]:
                    out[r][c] = v
    return out

